            for lo, hi in opts:
                v = lo if cur is None or lo > cur else cur
                cur = v
            rng = cur - opts[0][0]
            cand = (ops, rng)
            if best is None or cand[0] < best[0] or (cand[0] == best[0] and cand[1] < best[1]):
                best = cand
        return [best[0], best[1]]

