class Solution {
    public int[] minOperationsParityAlternating(int[] nums) {
        int n = nums.length;
        if (n == 1) return new int[]{0, 0};
        long bestOps = -1, bestRng = -1;
        for (int start = 0; start < 2; start++) {
            long[][] opts = new long[n][2];
            long ops = 0;
            for (int i = 0; i < n; i++) {
                int want = start ^ (i & 1);
                long x = nums[i];
                if (Math.floorMod(x, 2) == want) { opts[i][0] = x; opts[i][1] = x; }
                else { ops++; opts[i][0] = x - 1; opts[i][1] = x + 1; }
            }
            Arrays.sort(opts, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
            long cur = opts[0][0];
            for (long[] o : opts) cur = Math.max(cur, o[0]);
            long rng = cur - opts[0][0];
            if (bestOps == -1 || ops < bestOps || (ops == bestOps && rng < bestRng)) { bestOps = ops; bestRng = rng; }
        }
        return new int[]{(int) bestOps, (int) bestRng};
    }
}

