        n = len(nums)
        if n == 1:
            return [0, 0]
        def attempt(start):
            opts = []; ops = 0
            for i, x in enumerate(nums):
                if x % 2 == (start ^ (i & 1)): opts.append((x, x))
                else: ops += 1; opts.append((x - 1, x + 1))
            opts.sort()
            def feasible(D):
                lo = opts[0][0]
                cur = None
                for a, b in opts:
                    v = max(lo, a) if cur is None else max(cur, a)
                    if v > lo + D: return False
                    cur = v
                return True
            l, r = 0, max(b for _, b in opts) - min(a for a, _ in opts)
            while l < r:
                m = (l + r) // 2
                if feasible(m): r = m
                else: l = m + 1
            return ops, l
        cands = [attempt(0), attempt(1)]
        mo = min(c[0] for c in cands)
        return [mo, min(c[1] for c in cands if c[0] == mo)]

