class Solution {
public:
    vector<int> minOperationsParityAlternating(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return {0, 0};
        auto attempt = [&](int start) {
            vector<pair<long long,long long>> opts;
            long long ops = 0;
            for (int i = 0; i < n; i++) {
                long long x = nums[i];
                if (((x % 2) + 2) % 2 == (start ^ (i & 1))) opts.push_back({x, x});
                else { ops++; opts.push_back({x - 1, x + 1}); }
            }
            sort(opts.begin(), opts.end());
            auto feasible = [&](long long D) {
                long long lo = opts[0].first, cur = LLONG_MIN;
                for (auto& [a, b] : opts) {
                    long long v = max(cur, a);
                    if (v > lo + D) return false;
                    cur = v;
                }
                return true;
            };
            long long l = 0, r = opts.back().second - opts[0].first;
            while (l < r) { long long m = (l + r) / 2; if (feasible(m)) r = m; else l = m + 1; }
            return make_pair(ops, l);
        };
        auto a = attempt(0), b = attempt(1);
        long long mo = min(a.first, b.first), rng = LLONG_MAX;
        if (a.first == mo) rng = min(rng, a.second);
        if (b.first == mo) rng = min(rng, b.second);
        return {(int)mo, (int)rng};
    }
};

