class Solution {
    public int[] minOperationsParityAlternating(int[] nums) {
        int n = nums.length;
        if (n == 1) return new int[]{0, 0};
        long[][] res = new long[2][2];
        for (int s = 0; s < 2; s++) {
            long[][] opts = new long[n][2];
            long ops = 0;
            for (int i = 0; i < n; i++) {
                long x = nums[i];
                if (Math.floorMod(x, 2) == (s ^ (i & 1))) { opts[i][0] = x; opts[i][1] = x; }
                else { ops++; opts[i][0] = x - 1; opts[i][1] = x + 1; }
            }
            Arrays.sort(opts, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
            long lo = opts[0][0], hi = opts[n-1][1];
            long l = 0, r = hi - lo;
            while (l < r) {
                long m = (l + r) / 2, cur = Long.MIN_VALUE; boolean ok = true;
                for (long[] o : opts) { cur = Math.max(cur, o[0]); if (cur > lo + m) { ok = false; break; } }
                if (ok) r = m; else l = m + 1;
            }
            res[s][0] = ops; res[s][1] = l;
        }
        long mo = Math.min(res[0][0], res[1][0]), rng = Long.MAX_VALUE;
        for (long[] rr : res) if (rr[0] == mo) rng = Math.min(rng, rr[1]);
        return new int[]{(int) mo, (int) rng};
    }
}

